//! Flow-generated (regenerative / self-noise) sound power from fittings.
//!
//! ```text
//!     L_W(f) = 50 log10(V) + 10 log10(A) + K1(f) + 50
//! ```
//! V^5 velocity dependence — tight/fast paths regenerate fast.

use crate::autodiff::Dual;

use crate::metrics::octave::N_BANDS;

/// K_1(f) shape, peaking around 250 Hz. Generic fitting character.
const K1_BAND: [f64; N_BANDS] = [-8.0, -4.0, 0.0, -3.0, -7.0, -12.0, -18.0, -24.0];

const PWL_OFFSET_DB: f64 = 50.0;

/// PWL per octave band generated by a fitting with given velocity / area.
pub fn regenerative_pwl_db<const N: usize>(
    velocity_mps: Dual<N>,
    area_m2: Dual<N>,
) -> [Dual<N>; N_BANDS] {
    let v = velocity_mps.max_f(0.1);
    let a = area_m2.max_f(1e-4);
    let broadband = v.log10() * 50.0 + a.log10() * 10.0 + PWL_OFFSET_DB;
    let mut out = [Dual::<N>::constant(0.0); N_BANDS];
    for i in 0..N_BANDS {
        out[i] = broadband + K1_BAND[i];
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;
    use approx::assert_relative_eq;

    /// Doubling velocity adds 15.05 dB (= 50 log10 2) at every band.
    #[test]
    fn doubling_velocity_adds_fifty_log_two_db() {
        let a = Dual::<1>::constant(0.1);
        let lo = regenerative_pwl_db(Dual::<1>::constant(2.0), a);
        let hi = regenerative_pwl_db(Dual::<1>::constant(4.0), a);
        for i in 0..N_BANDS {
            assert_relative_eq!(
                hi[i].value - lo[i].value,
                50.0 * 2.0f64.log10(),
                max_relative = 1e-12
            );
        }
    }

    /// Doubling area adds 3.01 dB (= 10 log10 2) at every band.
    #[test]
    fn doubling_area_adds_three_db() {
        let v = Dual::<1>::constant(5.0);
        let lo = regenerative_pwl_db(v, Dual::<1>::constant(0.1));
        let hi = regenerative_pwl_db(v, Dual::<1>::constant(0.2));
        for i in 0..N_BANDS {
            assert_relative_eq!(
                hi[i].value - lo[i].value,
                10.0 * 2.0f64.log10(),
                max_relative = 1e-12
            );
        }
    }
}
